 internal static class ReleaseToolsTests {
  internal static int Run(string root){Directory.CreateDirectory(root);WorkflowStore.TestRoot=Path.Combine(root,"workflow");var checks=new List<string>();MainWindow window=null;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);checks.Add(label);};
   try{SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));
    string source=Directory.CreateDirectory(Path.Combine(root,"source")).FullName,target=Directory.CreateDirectory(Path.Combine(root,"target")).FullName;
    string file=Path.Combine(source,"sample.txt");File.WriteAllText(file,"original text",Encoding.UTF8);
    CopyResult copied;using(var control=new CopyControl())copied=new CopyEngine(new CopyOptions{Target=target},control,c=>new CopyDecision(CopyChoice.Skip),u=>{}).Run(new[]{file});
    check(copied.Errors.Count==0&&copied.Undo.Count==1,"Copy engine records a newly created file");var receipt=copied.Undo[0];SafeUndo.Record("copy",copied.Undo);var group=SafeUndo.Groups()[0];string destination=Path.Combine(target,"sample.txt");
    File.WriteAllText(destination,"modified text");bool rejected=false;try{SafeUndo.Apply(group,CancellationToken.None);}catch(IOException){rejected=true;}check(rejected&&File.ReadAllText(destination)=="modified text","Undo preserves a changed copy");
    File.WriteAllText(destination,"original text",Encoding.UTF8);SafeUndo.Apply(group,CancellationToken.None);check(!File.Exists(destination)&&File.Exists(file),"Undo removes a verified copy and preserves its source");
    string readOnlyFile=Path.Combine(source,"readonly.txt");File.WriteAllText(readOnlyFile,"read only");File.SetAttributes(readOnlyFile,FileAttributes.ReadOnly);using(var control=new CopyControl())copied=new CopyEngine(new CopyOptions{Target=target},control,c=>new CopyDecision(CopyChoice.Skip),u=>{}).Run(new[]{readOnlyFile});SafeUndo.Record("readonly",copied.Undo);SafeUndo.Apply(SafeUndo.Groups()[0],CancellationToken.None);check(!File.Exists(Path.Combine(target,"readonly.txt"))&&(File.GetAttributes(readOnlyFile)&FileAttributes.ReadOnly)!=0,"Undo removes a verified read-only copy without changing its source attributes");
    string restored=Path.Combine(source,"restored-by-copy.txt");using(var h=SafeUndo.Open(file,true))using(var input=new FileStream(h,FileAccess.Read))SafeUndo.RestoreByCopy(h,input,restored,CancellationToken.None);check(File.ReadAllBytes(restored).SequenceEqual(File.ReadAllBytes(file))&&File.GetLastWriteTimeUtc(restored)==File.GetLastWriteTimeUtc(file),"Cross-volume restore routine verifies bytes and preserves modification time");rejected=false;using(var h=SafeUndo.Open(file,true))using(var input=new FileStream(h,FileAccess.Read)){try{SafeUndo.RestoreByCopy(h,input,restored,CancellationToken.None);}catch(System.ComponentModel.Win32Exception){rejected=true;}}check(rejected&&File.ReadAllBytes(restored).SequenceEqual(File.ReadAllBytes(file)),"Copy-based restore does not overwrite an existing original");string cancelledRestore=Path.Combine(source,"cancelled-restore.txt");rejected=false;using(var h=SafeUndo.Open(file,true))using(var input=new FileStream(h,FileAccess.Read)){try{SafeUndo.RestoreByCopy(h,input,cancelledRestore,new CancellationToken(true));}catch(OperationCanceledException){rejected=true;}}check(rejected&&!File.Exists(cancelledRestore)&&File.Exists(file),"Cancelled copy-based restore cleans its own partial output and preserves the source");
    string renamed=Path.Combine(source,"renamed.txt");var rename=UndoReceipt.Capture(file,file,true);File.Move(file,renamed);rename.Target=renamed;SafeUndo.Record("rename",new[]{rename});File.WriteAllText(file,"collision");rejected=false;try{SafeUndo.Apply(SafeUndo.Groups()[0],CancellationToken.None);}catch(IOException){rejected=true;}check(rejected&&File.ReadAllText(file)=="collision"&&File.Exists(renamed),"Undo refuses an occupied original name");File.Delete(file);SafeUndo.Apply(SafeUndo.Groups()[0],CancellationToken.None);check(File.Exists(file)&&!File.Exists(renamed),"Undo restores a renamed file through its guarded handle");
    string folder=Directory.CreateDirectory(Path.Combine(source,"new-folder")).FullName;SafeUndo.Record("mkdir",new[]{UndoReceipt.Capture(folder,null,false)});string child=Path.Combine(folder,"keep.txt");File.WriteAllText(child,"keep");rejected=false;try{SafeUndo.Apply(SafeUndo.Groups()[0],CancellationToken.None);}catch(IOException){rejected=true;}check(rejected&&File.Exists(child),"Undo preserves a folder with new children");File.Delete(child);SafeUndo.Apply(SafeUndo.Groups()[0],CancellationToken.None);check(!Directory.Exists(folder),"Undo removes an owned empty folder");
    using(var control=new CopyControl())copied=new CopyEngine(new CopyOptions{Target=target,Move=true},control,c=>new CopyDecision(CopyChoice.Skip),u=>{}).Run(new[]{file});check(copied.Errors.Count==0&&copied.Undo.Count==1&&!File.Exists(file),"Fast move records the original file identity");SafeUndo.Record("move",copied.Undo);SafeUndo.Apply(SafeUndo.Groups()[0],CancellationToken.None);check(File.Exists(file)&&!File.Exists(destination),"Undo restores a same-volume move");
    string tree=Directory.CreateDirectory(Path.Combine(source,"tree")).FullName;Directory.CreateDirectory(Path.Combine(tree,"empty"));File.WriteAllText(Path.Combine(tree,"child.txt"),"child");using(var control=new CopyControl())copied=new CopyEngine(new CopyOptions{Target=target},control,c=>new CopyDecision(CopyChoice.Skip),u=>{}).Run(new[]{tree});check(copied.Errors.Count==0&&copied.Undo.Count==3,"Directory copy records its new files and empty directories");SafeUndo.Record("copy tree",copied.Undo);SafeUndo.Apply(SafeUndo.Groups()[0],CancellationToken.None);check(!Directory.Exists(Path.Combine(target,"tree"))&&File.Exists(Path.Combine(tree,"child.txt")),"Undo removes copied trees bottom-up without touching originals");
    string movedTree=Directory.CreateDirectory(Path.Combine(source,"moved-tree")).FullName;Directory.CreateDirectory(Path.Combine(movedTree,"empty"));File.WriteAllText(Path.Combine(movedTree,"content.txt"),"content");using(var control=new CopyControl())copied=new CopyEngine(new CopyOptions{Target=target,Move=true,Times=false},control,c=>new CopyDecision(CopyChoice.Skip),u=>{}).Run(new[]{movedTree});check(copied.Errors.Count==0&&!Directory.Exists(movedTree),"Copy-based move removes original directories after verified transfer");SafeUndo.Record("move tree",copied.Undo);SafeUndo.Apply(SafeUndo.Groups()[0],CancellationToken.None);check(File.ReadAllText(Path.Combine(movedTree,"content.txt"))=="content"&&Directory.Exists(Path.Combine(movedTree,"empty"))&&!Directory.Exists(Path.Combine(target,"moved-tree")),"Undo restores copy-based moves including empty directories");
    File.WriteAllText(destination,"existing");using(var control=new CopyControl())copied=new CopyEngine(new CopyOptions{Target=target,Rule=CopyRule.OverwriteAll},control,c=>new CopyDecision(CopyChoice.Overwrite),u=>{}).Run(new[]{file});check(copied.Errors.Count==0&&copied.Undo.Count==0,"Overwrite is explicitly excluded from safe Undo");
    var preset=new CopyOptions{Target=target,Filter="*.txt|private*",Verify=true,Permissions=true,ReadOnly=true,SkipHidden=true,Times=false,Attributes=false,EmptyFolders=false,Rule=CopyRule.Different,Move=true};WorkflowStore.Edit<CopyPresetSettings>("copy-presets.xml",s=>s.Items.Add(new CopyPreset{Name="Test",Options=preset}));var loaded=WorkflowStore.Load<CopyPresetSettings>("copy-presets.xml").Items[0].Options;check(loaded.Verify&&loaded.Filter==preset.Filter&&loaded.Rule==CopyRule.Different&&loaded.Move&&!loaded.Times&&!loaded.Attributes&&!loaded.EmptyFolders&&loaded.Permissions&&loaded.SkipHidden&&loaded.ReadOnly,"Preset roundtrip preserves target, masks, verification and flags");loaded.TargetIsFile=true;rejected=false;try{CopySetupDialog.ValidatePreset(loaded,false);}catch(IOException){rejected=true;}check(rejected,"Single-file presets are refused for multiple sources");
    var o=new FileSearchOptions{Text="needle"};check(o.MaximumTextBytes==0,"Plain text search defaults to unlimited file size");
    string text=Path.Combine(source,"large.txt");using(var output=new StreamWriter(text,false,new UTF8Encoding(false))){string chunk=new string('x',1048575)+"\n";for(int i=0;i<65;i++)output.Write(chunk);output.Write("prefix needle suffix\n");}var match=ContentSearch.Find(text,o,CancellationToken.None);check(match!=null&&match.Line==66&&match.Snippet.Contains("needle"),"Streaming search finds content after 64 MB and reports its line");
    using(var reader=new StringReader(new string('x',65533)+"\nneedle")){match=ContentSearch.Scan(reader,o,CancellationToken.None,null);check(match!=null&&match.Line==2,"Literal match survives a buffer boundary with correct line");}
    string encoded=Path.Combine(source,"encoded.txt");File.WriteAllText(encoded,"první\ndruhý žluťoučký",Encoding.GetEncoding(1250));match=ContentSearch.Find(encoded,new FileSearchOptions{Text="ŽLUŤOUČKÝ",EncodingCodePage=1250},CancellationToken.None);check(match!=null&&match.Line==2,"Windows-1250 and case-insensitive matching report the right line");
    using(var reader=new StringReader("first\nsecond42\n")){match=ContentSearch.Scan(reader,new FileSearchOptions{Text="second[0-9]+",TextRegex=true},CancellationToken.None,null);check(match!=null&&match.Line==2,"Regex search reports the matching line");}
    var cancelled=new CancellationToken(true);rejected=false;try{ContentSearch.Find(text,o,cancelled);}catch(OperationCanceledException){rejected=true;}check(rejected,"Streaming search observes cancellation");
    string docx=Path.Combine(source,"sample.docx");using(var output=File.Create(docx))using(var zip=new ZipArchive(output,ZipArchiveMode.Create)){using(var writer=new StreamWriter(zip.CreateEntry("word/document.xml").Open()))writer.Write("<w:document xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'><w:body><w:p><w:r><w:t>nee</w:t></w:r><w:r><w:t>dle in document</w:t></w:r></w:p></w:body></w:document>");}
    match=ContentSearch.Find(docx,new FileSearchOptions{Text="needle",DocumentText=true,MetadataInspecting=path=>{}},CancellationToken.None);check(match!=null&&match.Location.Contains("document.xml")&&match.Snippet.Contains("needle"),"Isolated DOCX worker matches words split across formatting runs");check(ContentSearch.Find(docx,o,CancellationToken.None)==null,"Document content extraction is opt-in");
    string badDocx=Path.Combine(source,"dtd.docx");using(var output=File.Create(badDocx))using(var zip=new ZipArchive(output,ZipArchiveMode.Create)){using(var writer=new StreamWriter(zip.CreateEntry("word/document.xml").Open()))writer.Write("<!DOCTYPE document [<!ENTITY payload SYSTEM 'file:///C:/Windows/win.ini'>]><document><p><t>&payload;</t></p></document>");}rejected=false;try{ContentSearch.Find(badDocx,new FileSearchOptions{Text="needle",DocumentText=true,MetadataInspecting=path=>{}},CancellationToken.None);}catch(IOException){rejected=true;}check(rejected,"Document worker rejects DTD and external entities");
    var searchHits=new List<SearchHit>();FileSearchEngine.Local(new FileSearchOptions{Root=encoded,Text="žluťoučký",EncodingCodePage=1250},new string[0],CancellationToken.None,searchHits.Add,w=>{});check(searchHits.Count==1&&searchHits[0].MatchLocation=="2"&&searchHits[0].Snippet.Contains("žluťoučký"),"File search exposes location and excerpt in actual search hits");
    string pdf=Path.Combine(source,"sample.pdf");var builder=new UglyToad.PdfPig.Writer.PdfDocumentBuilder();var font=builder.AddStandard14Font(UglyToad.PdfPig.Fonts.Standard14Fonts.Standard14Font.Helvetica);builder.AddPage(UglyToad.PdfPig.Content.PageSize.A4).AddText("needle PDF content",12,new UglyToad.PdfPig.Core.PdfPoint(30,700),font);File.WriteAllBytes(pdf,builder.Build());match=ContentSearch.Find(pdf,new FileSearchOptions{Text="needle",DocumentText=true,MetadataInspecting=path=>{}},CancellationToken.None);check(match!=null&&match.Location=="PDF 1","Isolated PDF worker reports the matching page");
    using(var lease=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read)){try{var locks=FileLocks.Find(new[]{file});check(locks.Any(x=>x.Pid==Process.GetCurrentProcess().Id),"Restart Manager identifies the process holding a real file handle");}catch(System.ComponentModel.Win32Exception ex){if(ex.NativeErrorCode!=29)throw;checks.Add("SKIP: live Restart Manager session unavailable (Windows error 29 in test environment)");}}
    check(MainWindow.LinkedRelative(source,Path.Combine(source,"a"))=="a"&&MainWindow.LinkedRelative(source,source)==""&&MainWindow.LinkedRelative(source,source+"-other")==null,"Linked browsing respects root boundaries");
    window=new MainWindow(source){Left=-18000,Top=-18000,WindowStartupLocation=WindowStartupLocation.Manual};window.Show();NavigationTests.WaitPanels(window);window.VerifyReleaseTools(source,target,check);window.Close();window=null;
    File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count(x=>!x.StartsWith("SKIP:"))+" checks; "+checks.Count(x=>x.StartsWith("SKIP:"))+" skipped"}));return 0;
   }catch(Exception ex){File.WriteAllText(Path.Combine(root,"result.txt"),"FAIL after "+checks.Count+" checks\n"+String.Join("\n",checks)+"\n"+ex);return 1;}finally{if(window!=null)window.Close();}
  }
 }
 public partial class CopySetupDialog {
  internal void VerifyLoadedPreset(bool move,Action<bool,string> check){var nodes=Descendants(this).ToList();var list=nodes.OfType<ComboBox>().First(x=>x.ItemsSource is CopyPreset[]);list.SelectedIndex=0;var button=nodes.OfType<Button>().First(x=>Convert.ToString(x.Content)==L.Text("tools1.load"));button.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));var o=CreateOptions(false);check(o.Move==move&&o.Filter=="*.txt|private*"&&o.Verify&&o.Rule==CopyRule.Different&&!o.Times&&!o.Attributes&&o.SkipHidden,"Loading a preset restores flags and preserves current "+(move?"move":"copy")+" mode");}
  static IEnumerable<DependencyObject> Descendants(DependencyObject root){yield return root;foreach(object child in LogicalTreeHelper.GetChildren(root)){var d=child as DependencyObject;if(d!=null)foreach(var node in Descendants(d))yield return node;}}
 }
 public partial class MainWindow {
  internal void VerifyReleaseTools(string a,string b,Action<bool,string> check){
   check(CommandMatches("Kopírovat soubory","kopirovat"),"Command search ignores accents");
   check(releaseCommands.Count>30&&releaseCommands.Any(x=>x.Id=="tools1.palette"),"Command palette registers existing menu actions and stable catalog IDs");
   var undo=releaseCommands.First(x=>x.Id=="tools1.undo");check(ParseGesture(Gesture(undo)).Key==Key.Z,"Undo exposes Ctrl+Z");
   customShortcuts=WorkflowStore.Edit<ShortcutSettings>("shortcuts.xml",data=>data.Items.Add(new ShortcutSetting{Id=undo.Id,Gesture="Ctrl+Shift+J"}));RefreshCommandGestures();check(undo.Item.InputGestureText=="Ctrl+Shift+J"&&SameGesture(ParseGesture("Ctrl+Shift+J"),Gesture(undo)),"Custom gesture overrides the menu and effective binding");check(WorkflowStore.Load<ShortcutSettings>("shortcuts.xml").Items.Any(x=>x.Id==undo.Id),"Custom shortcuts persist by stable command ID");
   check(SameGesture(ParseGesture("Ctrl+Shift+J"),"Ctrl+Shift+J")&&!SameGesture(ParseGesture("Ctrl+Shift+J"),"Ctrl+J"),"Shortcut collision comparison includes modifiers");
   check(ShortcutMatches(Key.Delete,ModifierKeys.None,"F8 / Delete")&&ShortcutMatches(Key.Add,ModifierKeys.None,"Num +")&&ShortcutMatches(Key.Back,ModifierKeys.None,"Backspace"),"Legacy aliases and numpad/navigation bindings participate in shortcut matching");
   int invoked=0;var probe=new ReleaseCommand{Id="test.probe",Default="F11",Item=new MenuItem(),Run=()=>invoked++};releaseCommands.Add(probe);customShortcuts.Items.Add(new ShortcutSetting{Id=probe.Id,Gesture="F12"});active.FocusFiles();var key=new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(this),0,Key.F12){RoutedEvent=Keyboard.PreviewKeyDownEvent};check(HandleReleaseKeys(key)&&key.Handled&&invoked==1,"A custom key event invokes its bound action");key=new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(this),0,Key.F11){RoutedEvent=Keyboard.PreviewKeyDownEvent};check(HandleReleaseKeys(key)&&invoked==1,"A remapped default key is suppressed");customShortcuts.Items.RemoveAll(x=>x.Id==probe.Id);releaseCommands.Remove(probe);
   right.Navigate(b,false);NavigationTests.Wait(right.NavigationTask);left.Navigate(a,false);NavigationTests.Wait(left.NavigationTask);ToggleLinkedBrowsing();
   string childA=Directory.CreateDirectory(Path.Combine(a,"linked-child")).FullName,childB=Directory.CreateDirectory(Path.Combine(b,"linked-child")).FullName;
   left.Navigate(childA,true);NavigationTests.Wait(left.NavigationTask);WaitLink(()=>String.Equals(right.CurrentPath,childB,StringComparison.OrdinalIgnoreCase));check(right.CurrentPath==childB&&linkedBrowsing,"Linked browsing mirrors an existing relative folder");
   string missing=Directory.CreateDirectory(Path.Combine(childA,"missing")).FullName;left.Navigate(missing,true);NavigationTests.Wait(left.NavigationTask);WaitLink(()=>operation.Text.Contains("missing"));check(right.CurrentPath==childB&&linkedBrowsing,"Missing linked counterpart leaves the other panel unchanged");
   left.Navigate(Path.GetDirectoryName(a),true);NavigationTests.Wait(left.NavigationTask);check(!linkedBrowsing&&!linkedMenu.IsChecked,"Leaving the captured root disables linked browsing");
   var dialog=new CopySetupDialog(this,new[]{new Entry{FullPath=Path.Combine(a,"sample.txt"),Name="sample.txt"}},b,new string[0]);check(dialog.Content!=null,"Copy dialog constructs with the saved preset controls");dialog.VerifyLoadedPreset(false,check);dialog.Close();var moveDialog=new CopySetupDialog(this,new[]{new Entry{FullPath=Path.Combine(a,"sample.txt"),Name="sample.txt"}},b,new string[0],true);moveDialog.VerifyLoadedPreset(true,check);moveDialog.Close();
  }
  static void WaitLink(Func<bool> done){var limit=DateTime.UtcNow.AddSeconds(10);while(!done()&&DateTime.UtcNow<limit){Dispatcher.CurrentDispatcher.Invoke(DispatcherPriority.Background,new Action(()=>{}));Thread.Sleep(2);}}
 }
